// Package prereq reports whether the npm tools the tests need have been installed, and fails a
// test that needs one that is missing with a single message that names the prerequisite and the
// setup command. Tests in this module and in the modules that consume it share it.
package prereq

import (
	"os"
	"path/filepath"
	"testing"
)

// SetupCommand installs the tools; the README documents it.
const SetupCommand = "go run github.com/KogenAI/kogen-verification/cmd/setup-tools"

// CucumberMissing is the message of every test that needs Cucumber and cannot find it.
const CucumberMissing = "missing prerequisite: Cucumber is not installed; run the setup command: " + SetupCommand

const cucumberEntry = "@cucumber/cucumber/bin/cucumber.js"

// Cucumber returns the node_modules folder that holds @cucumber/cucumber: the folder named by
// KOGEN_CUCUMBER when it holds Cucumber, otherwise testdata/tools/cucumber/node_modules of the Go
// module that contains the working directory. When neither holds it, the test fails.
func Cucumber(t testing.TB) string {
	t.Helper()
	if dir := os.Getenv("KOGEN_CUCUMBER"); holdsCucumber(dir) {
		return dir
	}
	if dir := moduleCucumber(); holdsCucumber(dir) {
		return dir
	}
	t.Fatal(CucumberMissing)
	return ""
}

func holdsCucumber(dir string) bool {
	if dir == "" {
		return false
	}
	info, err := os.Stat(filepath.Join(dir, cucumberEntry))
	return err == nil && info.Mode().IsRegular()
}

// moduleCucumber is the conventional install folder under the nearest folder at or above the
// working directory that holds a go.mod, or "" when there is none.
func moduleCucumber() string {
	dir, err := os.Getwd()
	if err != nil {
		return ""
	}
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return filepath.Join(dir, "testdata", "tools", "cucumber", "node_modules")
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return ""
		}
		dir = parent
	}
}

