// Command setup-tools installs the npm tools the tests need (Cucumber and Quint), at the
// versions pinned in testdata/tools, under testdata/tools of the working directory. A folder
// that lacks the pinned package.json or package-lock.json gets this module's copy first.
package main

import (
	"fmt"
	"os"
	"os/exec"
	"path"
	"path/filepath"

	"github.com/KogenAI/kogen-verification/testdata/tools"
)

func main() {
	for _, tool := range []string{"cucumber", "quint"} {
		dir := path.Join("testdata", "tools", tool)
		for _, name := range []string{"package.json", "package-lock.json"} {
			if err := provide(path.Join(dir, name)); err != nil {
				fail(err)
			}
		}
		install := exec.Command("npm", "ci", "--prefix", dir)
		install.Stdout, install.Stderr = os.Stdout, os.Stderr
		if err := install.Run(); err != nil {
			fail(fmt.Errorf("npm ci --prefix %s failed: %w", dir, err))
		}
	}
}

// provide writes the embedded copy of the file at rel unless the file already exists.
func provide(rel string) error {
	if _, err := os.Stat(filepath.FromSlash(rel)); err == nil {
		return nil
	}
	data, err := tools.Files.ReadFile(path.Join(path.Base(path.Dir(rel)), path.Base(rel)))
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.FromSlash(path.Dir(rel)), 0o755); err != nil {
		return err
	}
	return os.WriteFile(filepath.FromSlash(rel), data, 0o644)
}

func fail(err error) {
	fmt.Fprintln(os.Stderr, "setup-tools:", err)
	os.Exit(1)
}

