// Package prereq reports whether the npm tools the tests need have been installed, and fails a
// test that needs one that is missing with a single message that names the prerequisite and the
// setup command. Tests in this module and in the modules that consume it share it.
package prereq

import (
	"os"
	"path/filepath"
	"testing"
)

// SetupCommand installs the tools; the README documents it.
const SetupCommand = "go run github.com/KogenAI/kogen-verification/cmd/setup-tools"

